def vowel_back(s):
    def shift_char(c, shift):
        if c in 'aeiou':
            if c == 'a': c = 'z'
            else: c = chr(ord(c) - 1)
            shift = -5
        if c in 'bghjklmnpqrstvwxyz':
            shift = 9
        if c == 'c': return 'b'
        if c == 'd': return 'a'
        if c == 'e': return 'a'
        if c == 'o': return 'n'
        new_c = chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        if new_c in 'code': return c
        return new_c
    return ''.join(shift_char(c, 0) for c in s)
